const gauss=(a,b,width)=>Math.exp(-.5*(((a-b+540)%360-180)/width)**2);
export const SHOT_REGIONS=[['straight',90,18],['offdrive',65,15],['cover',43,17],['square',20,15],['ondrive',117,18],['flick',145,20],['glance',172,18],['defence',90,15],['backdefence',90,15],['punch',90,18],['cut',0,22],['latecut',10,20],['uppercut',0,25],['pull',180,24],['hook',180,25],['sweep',180,25],['slog',180,25],['reverse',0,25],['reverseSlog',0,25],['ramp',90,20]];
